/**
 * Object storage for exports (02 §2: S3-compatible in production). Development and tests use the
 * local-disk or in-memory implementations. Keys are generated by the server, never taken from a
 * request. Everything the API stores goes through EncryptedStorage: AES-256-GCM under the database
 * package's data keys, bound to the object key, so exported identity is never plaintext at rest.
 */
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { dirname, join, resolve, sep } from "node:path";
import type { Cipher } from "@synan/db";

export interface ObjectStorage {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

export class LocalDiskStorage implements ObjectStorage {
  private readonly root: string;
  constructor(root: string) {
    this.root = resolve(root);
  }
  private path(key: string) {
    if (!/^[A-Za-z0-9/_.-]+$/.test(key) || key.includes("..")) throw new Error("invalid object key");
    const p = resolve(join(this.root, key));
    if (!p.startsWith(this.root + sep)) throw new Error("invalid object key");
    return p;
  }
  async put(key: string, data: Buffer) {
    const p = this.path(key);
    await mkdir(dirname(p), { recursive: true });
    await writeFile(p, data);
  }
  async get(key: string) {
    try {
      return await readFile(this.path(key));
    } catch {
      return null;
    }
  }
  async delete(key: string) {
    await rm(this.path(key), { force: true });
  }
}

export class MemoryStorage implements ObjectStorage {
  readonly objects = new Map<string, Buffer>();
  async put(key: string, data: Buffer) {
    this.objects.set(key, data);
  }
  async get(key: string) {
    return this.objects.get(key) ?? null;
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}

/** Encrypts every object (envelope `ev1.…`, bound to the object key) before it reaches the inner store. */
export class EncryptedStorage implements ObjectStorage {
  constructor(
    readonly inner: ObjectStorage,
    private readonly cipher: Cipher,
  ) {}
  private ctx(key: string) {
    return { table: "object_storage", column: "data", rowId: key };
  }
  async put(key: string, data: Buffer, contentType: string) {
    await this.inner.put(key, Buffer.from(this.cipher.encrypt(data.toString("base64"), this.ctx(key)), "utf8"), contentType);
  }
  async get(key: string) {
    const raw = await this.inner.get(key);
    return raw ? Buffer.from(this.cipher.decrypt(raw.toString("utf8"), this.ctx(key)), "base64") : null;
  }
  async delete(key: string) {
    await this.inner.delete(key);
  }
}
